function [h] = hloc_of(hl)
%HLOC_OF  The local-time harmonics at a local solar time [rad].
%   hl: real[1] (passed a plain number)
%   returns h: Hloc (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    h = asils.models.dtm2020.Hloc_zero();
    h = asils.models.dtm2020.Hloc_zero();
    h.ch = cos(hl);
    h.sh = sin(hl);
    h.c2h = (asils.pc.pow_(h.ch, 2) - asils.pc.pow_(h.sh, 2));
    h.s2h = ((2 * h.ch) * h.sh);
    h.c3h = ((h.c2h * h.ch) - (h.s2h * h.sh));
    h.s3h = ((h.s2h * h.ch) + (h.c2h * h.sh));
end
